"use client";

import { createContext, useContext } from "react";
import type { ReactNode } from "react";

/*
 * Account state read by the profile and account avatars: the auth context,
 * the account check query, workspace plans, profile visibility and the
 * profile query for the signed-in user. The host supplies their
 * results through AccountServicesProvider, so a host without that backend
 * can feed local account and workspace data into the same logic.
 */

/** The workspace plans. */
const WORKSPACE_PLANS: ReadonlySet<string> = new Set([
  "business",
  "enterprise",
  "metered_plan",
  "cbp_automation",
  "cbp_trial",
  "viewer_plan",
  "deprecated_enterprise",
  "hc",
  "consumption",
  "finserv",
  "law",
  "ent26",
  "education",
  "edu_plus",
  "edu_pro",
  "edu",
  "deprecated_edu",
  "k12",
  "quorum",
]);

export const isWorkspacePlan = (plan: string | null | undefined): boolean =>
  plan !== null && plan !== undefined && WORKSPACE_PLANS.has(plan);

/** The fields of the auth context that the avatars read. */
export interface AccountAuth {
  accountId: string | null;
  authMethod: string | null;
  isLoading: boolean;
  planAtLogin: string | null;
  userId: string | null;
}

export interface AccountInfo {
  id: string;
  plan_type?: string | null;
}

/** The accounts check response: `account_ordering` ids and `accounts`. */
export interface AccountCheck {
  account_ordering?: readonly string[];
  accounts?: readonly AccountInfo[];
}

export interface AccountCheckQuery {
  data?: AccountCheck | null;
  isError: boolean;
  isLoading: boolean;
}

export interface WorkspaceSettings {
  member_profiles_enabled?: boolean;
}

export interface WorkspaceSettingsQuery {
  data?: WorkspaceSettings | null;
  isLoading: boolean;
}

export interface ProfileUsage {
  imageUrl: string | null;
}

export interface ProfileUsageQuery {
  data?: ProfileUsage | null;
  isLoading: boolean;
}

/**
 * What the host supplies. Every reader receives `enabled`
 * query does. A disabled read starts no fetch and is not loading, but it
 * still answers the data already cached for its key: a disabled useQuery
 * and the disabled reader of querySignal
 * keep the data of their query.
 */
export interface AccountServices {
  /** Whether account inputs are available. Defaults to true, the store default. */
  accountInputsAvailable?: boolean;
  accountCheck: AccountCheckQuery;
  auth: AccountAuth;
  /** The workspace settings of an account. */
  readWorkspaceSettings: (
    accountId: string,
    enabled: boolean
  ) => WorkspaceSettingsQuery;
  /** The signed-in user's profile, whose imageUrl is the profile picture. */
  readProfileUsage: (input: {
    accountId: string | null;
    enabled: boolean;
    /** Uses an account-specific key while pictures are visible, otherwise a shared disabled key. */
    queryKey: readonly (string | null)[];
    userId: string | null;
  }) => ProfileUsageQuery;
  /** The workspace person's avatar URL for this account user id. */
  readSpacePersonAvatar: (
    accountUserId: string,
    enabled: boolean
  ) => string | null;
}

const AccountServicesContext = createContext<AccountServices | null>(null);

export const AccountServicesProvider = ({
  children,
  services,
}: {
  children?: ReactNode;
  services: AccountServices;
}) => (
  <AccountServicesContext.Provider value={services}>
    {children}
  </AccountServicesContext.Provider>
);

const useAccountServices = (): AccountServices => {
  const services = useContext(AccountServicesContext);

  if (services === null) {
    throw new Error("AuthProvider is required before calling useAuth");
  }

  return services;
};

/** The signed-in auth state. */
export const useAuth = (): AccountAuth => useAccountServices().auth;

/** The first account of `account_ordering`, found in `accounts`. */
export const selectActiveAccount = (
  check: AccountCheck | null | undefined
): AccountInfo | undefined => {
  const ordering = check?.account_ordering ?? [];
  const first = ordering.length > 0 ? ordering[0] : undefined;

  if (first === undefined || first === "") {
    return undefined;
  }

  return check?.accounts?.find((account) => account.id === first);
};

export interface ProfileVisibility {
  isProfileVisibilityLoading: boolean;
  isProfileVisible: boolean;
}

interface VisibilityInputs {
  accountCheck: AccountCheckQuery;
  auth: AccountAuth;
  readWorkspaceSettings: AccountServices["readWorkspaceSettings"];
}

const isMissing = (
  value: string | null | undefined
): value is null | undefined => value === null || value === undefined;

/** Settings have loaded and member profiles are not switched off. */
const allowsMemberProfiles = (settings: WorkspaceSettings | null | undefined) =>
  settings !== null &&
  settings !== undefined &&
  settings.member_profiles_enabled !== false;

/**
 * Whether profile pictures show. Needs an account sign-in and a known
 * plan. A workspace plan also needs member profiles enabled in the
 * workspace settings (any value but false, once they have loaded).
 */
export const resolveProfileVisibility = ({
  accountCheck,
  auth,
  readWorkspaceSettings,
}: VisibilityInputs): ProfileVisibility => {
  const { isError } = accountCheck;
  const signedIn = auth.authMethod === "account";
  const account = selectActiveAccount(accountCheck.data);
  const id = account?.id ?? auth.accountId;
  const plan = account?.plan_type ?? auth.planAtLogin;
  const workspacePlan = isWorkspacePlan(plan);
  const planPending = accountCheck.isLoading || isMissing(plan);
  const known = signedIn && !isError && !planPending;

  const settings = readWorkspaceSettings(
    id ?? "",
    known && id !== null && workspacePlan
  );

  const membersVisible = !isError && allowsMemberProfiles(settings.data);
  const visible = !planPending && (!workspacePlan || membersVisible);
  const settingsPending = workspacePlan && (id === null || settings.isLoading);

  return {
    isProfileVisibilityLoading:
      auth.isLoading || (signedIn && (planPending || settingsPending)),
    isProfileVisible: signedIn && visible,
  };
};

export const useProfileVisibility = (): ProfileVisibility =>
  resolveProfileVisibility(useAccountServices());

/**
 * The signed-in user's profile query. It runs only while profile
 * pictures are visible and the account inputs are available. It uses a separate
 * disabled key while they are hidden, so cached
 * data of the signed-in user is not read while they are hidden.
 */
export const useAccountProfile = ({
  accountId,
  enabled,
  userId,
}: {
  accountId: string | null;
  enabled: boolean;
  userId: string | null;
}): ProfileUsageQuery => {
  const services = useAccountServices();
  const { isProfileVisible } = useProfileVisibility();
  const visible = isProfileVisible && (services.accountInputsAvailable ?? true);

  return services.readProfileUsage({
    accountId,
    enabled: visible && enabled,
    queryKey: visible
      ? ["profile", "usage", userId, accountId]
      : ["profile", "usage", "disabled"],
    userId,
  });
};

/** Returns null when no account user id is given. */
export const useSpacePersonAvatar = (
  accountUserId: string | null,
  enabled: boolean
): string | null => {
  const services = useAccountServices();

  return accountUserId === null
    ? null
    : services.readSpacePersonAvatar(accountUserId, enabled);
};

"use client";

/* oxlint-disable anti-slop/no-shape-in-symbol-names -- The public names are shape, animateShape and AvatarShape. */

import { useReducedMotion } from "@/lib/reduced-motion";
import { useEffect, useId, useLayoutEffect, useRef } from "react";
import type { CSSProperties, ReactNode } from "react";

type CustomProperties = CSSProperties & Record<`--${string}`, number | string>;

export type AvatarShapeName =
  | "blossom"
  | "circle"
  | "oval"
  | "scalloped"
  | "square";

// The outline of each avatar shape.
const shapes = {
  blossom: {
    path: "M27.8 0C32.3 0 36.3 1.8 39.3 4.8C40.6 4.4 42.1 4.2 43.5 4.2C52.5 4.2 59.8 11.5 59.8 20.5C59.8 21.9 59.6 23.4 59.2 24.7C62.2 27.7 64 31.7 64 36.2C64 43.7 58.9 50.1 51.9 51.9C50.1 58.9 43.7 64 36.2 64C31.7 64 27.7 62.2 24.7 59.2C23.4 59.6 21.9 59.8 20.5 59.8C11.5 59.8 4.2 52.5 4.2 43.5C4.2 42.1 4.4 40.6 4.8 39.3C1.8 36.3 0 32.3 0 27.8C0 20.3 5.1 13.9 12.1 12.1C13.9 5.1 20.3 0 27.8 0Z",
    transform: "matrix(0.015625 0 0 0.015625 0 0)",
  },
  circle: {
    path: "M.5 0 A.5 .5 0 1 1 .5 1 A.5 .5 0 1 1 .5 0 Z",
    transform: "matrix(1 0 0 1 0 0)",
  },
  oval: {
    path: "M.5 0 A.42 .5 0 1 1 .5 1 A.42 .5 0 1 1 .5 0 Z",
    transform: "matrix(1 0 0 1 0 0)",
  },
  scalloped: {
    path: "M26.5 0C28.7 0 30.6 1.4 31.3 3.3C32.2 2.5 33.4 2 34.7 2C37.5 2 39.8 4.4 39.8 7.2C39.8 7.6 39.8 7.9 39.7 8.2C40.3 8 41 7.9 41.7 7.9C44.5 7.9 46.8 10.2 46.8 13C46.8 14.4 46.2 15.7 45.3 16.7C45.6 16.6 46 16.6 46.3 16.6C49.1 16.6 51.4 18.9 51.4 21.7C51.4 24.2 49.8 26.2 47.5 26.7C47.5 26.8 47.5 26.8 47.5 26.9C47.7 26.8 47.8 26.8 47.9 26.8C50.8 26.8 53.1 29.2 53.1 32C53.1 34.8 50.8 37.2 47.9 37.2C47.8 37.2 47.7 37.2 47.5 37.1C47.5 37.2 47.5 37.2 47.5 37.3C49.8 37.8 51.4 39.8 51.4 42.3C51.4 45.1 49.1 47.4 46.3 47.4C46 47.4 45.6 47.4 45.3 47.3L45.3 47.3C46.2 48.3 46.8 49.6 46.8 51C46.8 53.8 44.5 56.1 41.7 56.1C41 56.1 40.3 56 39.7 55.8C39.8 56.1 39.8 56.4 39.8 56.8C39.8 59.6 37.6 62 34.7 62C33.4 62 32.2 61.5 31.3 60.7C30.6 62.6 28.7 64 26.5 64C24.3 64 22.5 62.6 21.7 60.7C20.8 61.5 19.6 62 18.3 62C15.5 62 13.2 59.6 13.2 56.8C13.2 56.4 13.3 56.1 13.3 55.8C12.7 56 12.1 56.1 11.4 56.1C8.6 56.1 6.3 53.8 6.3 51C6.3 49.6 6.8 48.3 7.8 47.3C7.4 47.4 7.1 47.4 6.7 47.4C3.9 47.4 1.6 45.1 1.6 42.3C1.6 39.8 3.3 37.8 5.5 37.3C5.5 37.2 5.5 37.2 5.5 37.1C5.4 37.2 5.2 37.2 5.1 37.2C2.3 37.2 0 34.8 0 32C0 29.2 2.3 26.8 5.1 26.8C5.2 26.8 5.4 26.8 5.5 26.9C5.5 26.8 5.5 26.8 5.5 26.7C3.3 26.2 1.6 24.2 1.6 21.7C1.6 18.9 3.9 16.6 6.7 16.6C7.1 16.6 7.4 16.6 7.8 16.7C6.8 15.7 6.3 14.4 6.3 13C6.3 10.2 8.6 7.9 11.4 7.9C12.1 7.9 12.7 8 13.3 8.2C13.3 7.9 13.2 7.6 13.2 7.2C13.2 4.4 15.5 2 18.3 2C19.6 2 20.8 2.5 21.7 3.3C22.5 1.4 24.3 0 26.5 0Z",
    transform: "matrix(0.015625 0 0 0.015625 0.0852 0)",
  },
  square: {
    path: "M.28 0 H.72 A.28 .28 0 0 1 1 .28 V.72 A.28 .28 0 0 1 .72 1 H.28 A.28 .28 0 0 1 0 .72 V.28 A.28 .28 0 0 1 .28 0 Z",
    transform: "matrix(1 0 0 1 0 0)",
  },
} as const;

type Point = readonly [number, number];

interface MotionControls {
  stop: () => void;
}

const RAY_COUNT = 320;
const PATH_SAMPLE_COUNT = 1280;
const MORPH_DURATION_MS = 300;
const SPIN_DELAY_MS = 960;
const FULL_TURN_DEGREES = 360;
const MILLISECONDS_PER_SECOND = 1000;
const SPRING_STIFFNESS = 66;
const SPRING_DAMPING = 13;
const SPRING_MASS = 1;
const SPRING_REST_DELTA = 0.05;
const SPRING_REST_SPEED = 1;
const SPRING_VELOCITY_SAMPLE_SECONDS = 0.006;
const CENTER = 0.5;

const sampleCache = new Map<AvatarShapeName, Point[]>();

// Sample the outline, then cast RAY_COUNT rays from the
// centre and keep the farthest hit, so every shape has the same point count.
const sampleShape = (name: AvatarShapeName): Point[] => {
  const cached = sampleCache.get(name);

  if (cached !== undefined) {
    return cached;
  }

  const shape = shapes[name];
  const path = document.createElementNS("http://www.w3.org/2000/svg", "path");

  path.setAttribute("d", shape.path);

  const matrix = new DOMMatrix(shape.transform.replaceAll(" ", ", "));
  const length = path.getTotalLength();

  const outline = Array.from({ length: PATH_SAMPLE_COUNT }, (_, index) => {
    const point = matrix.transformPoint(
      path.getPointAtLength((length * index) / PATH_SAMPLE_COUNT)
    );

    return [point.x, point.y] as const;
  });

  const rays = Array.from({ length: RAY_COUNT }, (_, index) => {
    const angle = (index / RAY_COUNT) * Math.PI * 2 - Math.PI / 2;
    const cos = Math.cos(angle);
    const sin = Math.sin(angle);
    let reach = 0;

    for (const [edgeIndex, start] of outline.entries()) {
      const end = outline[(edgeIndex + 1) % outline.length];
      const dx = end[0] - start[0];
      const dy = end[1] - start[1];
      const cross = cos * dy - sin * dx;

      if (Math.abs(cross) < 1e-10) {
        continue;
      }

      const offsetX = start[0] - CENTER;
      const offsetY = start[1] - CENTER;
      const distance = (offsetX * dy - offsetY * dx) / cross;
      const along = (offsetX * sin - offsetY * cos) / cross;

      if (distance >= 0 && along >= 0 && along <= 1) {
        reach = Math.max(reach, distance);
      }
    }

    return [CENTER + cos * reach, CENTER + sin * reach] as const;
  });

  sampleCache.set(name, rays);

  return rays;
};

const toPolygonPath = (points: readonly Point[]) =>
  `${points
    .map(
      ([x, y], index) =>
        `${index === 0 ? "M" : "L"}${x.toFixed(5)} ${y.toFixed(5)}`
    )
    .join("")}Z`;

const wave = (value: number) =>
  1 -
  Math.exp(-7.6 * value) *
    (Math.cos(9.5 * value) + 0.72 * Math.sin(9.5 * value));

// A damped oscillation normalised to end at 1.
const morphEase = (progress: number) => wave(progress) / wave(1);

const runTween = ({
  duration,
  ease,
  onComplete,
  onUpdate,
}: {
  duration: number;
  ease: (progress: number) => number;
  onComplete: () => void;
  onUpdate: (value: number) => void;
}): MotionControls => {
  let frame = 0;
  let startedAt: number | null = null;

  const tick = (now: number) => {
    startedAt ??= now;

    const progress = Math.min((now - startedAt) / duration, 1);

    onUpdate(ease(progress));

    if (progress >= 1) {
      onComplete();

      return;
    }

    frame = requestAnimationFrame(tick);
  };

  frame = requestAnimationFrame(tick);

  return {
    stop: () => {
      cancelAnimationFrame(frame);
    },
  };
};

// Solve the underdamped spring from rest and stop at the speed and distance limits.
const runSpin = ({
  onComplete,
  onUpdate,
}: {
  onComplete: () => void;
  onUpdate: (value: number) => void;
}): MotionControls => {
  const target = FULL_TURN_DEGREES;
  const naturalFrequency = Math.sqrt(SPRING_STIFFNESS / SPRING_MASS);

  const dampingRatio =
    SPRING_DAMPING / (2 * Math.sqrt(SPRING_STIFFNESS * SPRING_MASS));

  const dampedFrequency = naturalFrequency * Math.sqrt(1 - dampingRatio ** 2);

  const valueAt = (seconds: number) =>
    target -
    Math.exp(-dampingRatio * naturalFrequency * seconds) *
      (((dampingRatio * naturalFrequency * target) / dampedFrequency) *
        Math.sin(dampedFrequency * seconds) +
        target * Math.cos(dampedFrequency * seconds));

  let frame = 0;
  let startedAt: number | null = null;

  const tick = (now: number) => {
    startedAt ??= now;

    const seconds = (now - startedAt) / MILLISECONDS_PER_SECOND;
    const value = valueAt(seconds);

    const velocity =
      (value - valueAt(Math.max(0, seconds - SPRING_VELOCITY_SAMPLE_SECONDS))) /
      SPRING_VELOCITY_SAMPLE_SECONDS;

    const settled =
      Math.abs(velocity) <= SPRING_REST_SPEED &&
      Math.abs(target - value) <= SPRING_REST_DELTA;

    onUpdate(settled ? target : value);

    if (settled) {
      onComplete();

      return;
    }

    frame = requestAnimationFrame(tick);
  };

  frame = requestAnimationFrame(tick);

  return {
    stop: () => {
      cancelAnimationFrame(frame);
    },
  };
};

export interface AvatarShapeProps {
  /** Morph between outlines over 300ms when `shape` changes. */
  animateShape?: boolean;
  children?: ReactNode;
  /** After 960ms of hover, the blossom outline turns once. Needs `animateShape`. */
  hovered?: boolean;
  shape: AvatarShapeName;
}

/**
 * Clips its children to a named outline with an objectBoundingBox clip path.
 */
export const AvatarShape = ({
  animateShape = false,
  children,
  hovered = false,
  shape,
}: AvatarShapeProps) => {
  const clipId = useId();
  const reducedMotion = useReducedMotion();
  const pathRef = useRef<SVGPathElement>(null);
  const previousShape = useRef(shape);
  const morphPoints = useRef<Point[] | null>(null);
  const spin = useRef<MotionControls | null>(null);

  const clipStyle: CustomProperties = {
    "--avatar-clip-path": `url(#${clipId})`,
  };

  useLayoutEffect(() => {
    const path = pathRef.current;
    const previous = previousShape.current;

    previousShape.current = shape;
    spin.current?.stop();
    spin.current = null;
    path?.setAttribute("transform", shapes[shape].transform);

    const settle = () => {
      path?.setAttribute("d", shapes[shape].path);
      path?.setAttribute("transform", shapes[shape].transform);
      morphPoints.current = null;
    };

    const morphs =
      path !== null &&
      animateShape &&
      !reducedMotion &&
      (previous !== shape || morphPoints.current !== null);

    let morph: MotionControls | null = null;

    if (morphs) {
      const from = morphPoints.current ?? sampleShape(previous);
      const to = sampleShape(shape);

      path.removeAttribute("transform");
      path.setAttribute("d", toPolygonPath(from));
      morph = runTween({
        duration: MORPH_DURATION_MS,
        ease: morphEase,
        onComplete: settle,
        onUpdate: (progress) => {
          const next = from.map(
            (point, index) =>
              [
                point[0] + (to[index][0] - point[0]) * progress,
                point[1] + (to[index][1] - point[1]) * progress,
              ] as const
          );

          morphPoints.current = next;
          path.setAttribute("d", toPolygonPath(next));
        },
      });
    } else {
      settle();
    }

    return () => {
      morph?.stop();
    };
  }, [shape, animateShape, reducedMotion]);

  useEffect(
    () => () => {
      spin.current?.stop();
    },
    []
  );

  useEffect(() => {
    const spins =
      hovered && animateShape && !reducedMotion && shape === "blossom";

    const timer = spins
      ? setTimeout(() => {
          // oxlint-disable-next-line eslint/logical-assignment-operators -- React Compiler does not support ??=.
          spin.current =
            spin.current ??
            runSpin({
              onComplete: () => {
                pathRef.current?.setAttribute(
                  "transform",
                  shapes[shape].transform
                );
                spin.current = null;
              },
              onUpdate: (degrees) => {
                pathRef.current?.setAttribute(
                  "transform",
                  `rotate(${degrees} .5 .5) ${shapes[shape].transform}`
                );
              },
            });
        }, SPIN_DELAY_MS)
      : undefined;

    return () => {
      clearTimeout(timer);
    };
  }, [hovered, animateShape, reducedMotion, shape]);

  return (
    <span className="relative inline-flex shrink-0">
      <svg aria-hidden="true" className="absolute size-0" focusable="false">
        <defs>
          <clipPath clipPathUnits="objectBoundingBox" id={clipId}>
            <path
              d={shapes[shape].path}
              ref={pathRef}
              transform={shapes[shape].transform}
            />
          </clipPath>
        </defs>
      </svg>
      <span
        className="relative inline-flex [clip-path:var(--avatar-clip-path)]"
        style={clipStyle}
      >
        {children}
      </span>
    </span>
  );
};

"use client";

import {
  TooltipHint,
  TooltipProvider,
} from "@/components/ui/tooltip";
import { useReducedMotion } from "@/lib/reduced-motion";
import { cn } from "@/lib/utils";
import { useCallback, useEffect, useRef, useState } from "react";
import type {
  CSSProperties,
  KeyboardEvent,
  MouseEvent,
  ReactNode,
} from "react";

type CustomProperties = CSSProperties & Record<`--${string}`, number | string>;

export interface FacepilePerson {
  /** The avatar element drawn in the stack and in the overflow list. */
  avatar: ReactNode;
  id: string;
  /** Shown beside the avatar in the overflow list; the name when absent. */
  label?: string;
  name: string;
}

export interface FacepileProps {
  /** Which end of the stack lies on top. */
  front?: "first" | "last";
  /** When false the overflow count is plain text, out of the tab order. */
  interactive?: boolean;
  overflowSideOffset?: number;
  people: readonly FacepilePerson[];
  /** Drawn when there are no people. */
  placeholder?: ReactNode;
  size?: "md" | "sm";
}

const MAX_VISIBLE = 5;
const FADE_DURATION_MS = 160;
const FADE_START_OPACITY = 0.88;

// Each avatar fades in with this easing.
const FADE_EASING = "cubic-bezier(0.23, 1, 0.32, 1)";

type OverflowOpen = "click" | "hover" | null;

const noCleanup = () => {
  // Nothing was started, so there is nothing to stop.
};

const moreLabel = (count: number) =>
  new Intl.PluralRules("en-US").select(count) === "one"
    ? `${count} more person`
    : `${count} more people`;

interface FadeState {
  first: boolean;
  reducedMotion: boolean;
}

// Fade on mount and when an avatar becomes first. Interrupted fades continue
// from their current opacity. Reduced motion settles at full opacity.
const fadePlays = (
  before: FadeState | null,
  now: FadeState,
  blockInitial: boolean
) => {
  if (before === null) {
    return !blockInitial && !now.reducedMotion;
  }

  return (
    now.first && !now.reducedMotion && (!before.first || before.reducedMotion)
  );
};

const FacepileAvatar = ({
  blockInitial,
  children,
  front,
  index,
  reducedMotion,
  total,
  visibleCount,
}: {
  blockInitial: boolean;
  children: ReactNode;
  front: "first" | "last";
  index: number;
  reducedMotion: boolean;
  total: number;
  visibleCount: number;
}) => {
  const ref = useRef<HTMLSpanElement>(null);
  const previous = useRef<FadeState | null>(null);
  const running = useRef<Animation | null>(null);
  const hidden = index >= visibleCount;
  const first = index === 0;

  const stackOrder: CustomProperties = {
    "--facepile-z": front === "first" ? total - index : index,
  };

  useEffect(() => {
    const now = { first, reducedMotion };
    const before = previous.current;

    previous.current = now;

    if (fadePlays(before, now, blockInitial)) {
      running.current?.cancel();
      running.current =
        ref.current?.animate(
          [{ opacity: FADE_START_OPACITY }, { opacity: 1 }],
          { duration: FADE_DURATION_MS, easing: FADE_EASING }
        ) ?? null;
    } else if (first && reducedMotion && before?.reducedMotion === false) {
      running.current?.cancel();
      running.current = null;
    } else if (before?.first === true && !first && !before.reducedMotion) {
      const fade = running.current;

      if (fade?.playState === "running" && ref.current !== null) {
        const current = getComputedStyle(ref.current).opacity;

        fade.cancel();
        running.current = reducedMotion
          ? null
          : ref.current.animate([{ opacity: current }, { opacity: 1 }], {
              duration: FADE_DURATION_MS,
              easing: FADE_EASING,
            });
      }
    }
  }, [blockInitial, first, reducedMotion]);

  return (
    <span
      aria-hidden={hidden || undefined}
      className={cn(
        "pointer-events-auto relative z-(--facepile-z) inline-flex shrink-0",
        hidden && "invisible"
      )}
      data-page-facepile-avatar
      inert={hidden}
      ref={ref}
      style={stackOrder}
    >
      {children}
    </span>
  );
};

// Measures the stack and the +N control, and keeps the number of avatars that
// fit. The control sits after the last fitting avatar.
const observeFacepile = ({
  onCount,
  root,
  shownLength,
  total,
}: {
  onCount: (count: number) => void;
  root: HTMLSpanElement | null;
  shownLength: number;
  total: number;
}) => {
  const stack = root?.firstElementChild;
  const control = root?.lastElementChild;

  if (
    root === null ||
    !(stack instanceof HTMLElement) ||
    !(control instanceof HTMLElement)
  ) {
    return noCleanup;
  }

  control.style.minWidth = "";

  let widest = 0;

  const update = () => {
    widest = Math.max(widest, control.offsetWidth);
    control.style.minWidth = `${widest}px`;

    // oxlint-disable-next-line unicorn/prefer-number-coercion -- The value has a px suffix, so Number would give NaN.
    const controlPadding = Number.parseFloat(
      getComputedStyle(control).paddingInlineStart
    );

    const reserved = widest - controlPadding;

    stack.style.paddingInlineEnd = total > shownLength ? `${reserved}px` : "";

    const fitsWithoutControl =
      total === shownLength && stack.clientWidth <= root.clientWidth;

    const limit = fitsWithoutControl
      ? root.clientWidth
      : root.clientWidth - reserved;

    const rtl = getComputedStyle(root).direction === "rtl";
    let count = 0;
    let edge = 0;

    for (const item of stack.querySelectorAll("[data-page-facepile-avatar]")) {
      if (!(item instanceof HTMLElement)) {
        continue;
      }

      const end = rtl
        ? stack.clientWidth - item.offsetLeft
        : item.offsetLeft + item.offsetWidth;

      if (fitsWithoutControl || end <= limit) {
        count += 1;
        edge = end;
      }
    }

    control.style.insetInlineStart = `${Math.max(0, edge - controlPadding)}px`;
    onCount(count);
  };

  const observer = new ResizeObserver(update);

  observer.observe(root);
  observer.observe(stack);
  observer.observe(control);
  update();

  return () => {
    observer.disconnect();
  };
};

/**
 * Overlapping avatars that fit their box, with a +N count for the rest.
 * The overflow list opens on the Base UI tooltip.
 */
export const Facepile = ({
  front = "first",
  interactive = true,
  overflowSideOffset,
  people,
  placeholder,
  size = "md",
}: FacepileProps) => {
  const reducedMotion = useReducedMotion();
  const total = people.length;
  const shown = people.slice(0, MAX_VISIBLE);
  const shownLength = Math.min(total, MAX_VISIBLE);
  const [visibleCount, setVisibleCount] = useState(shownLength);
  const [open, setOpen] = useState<OverflowOpen>(null);
  const hiddenCount = total - Math.min(visibleCount, shownLength);

  // The ref callback keeps its identity until the number shown or the total
  // changes, like the memoised callback ref. React calls a callback
  // ref again, after its cleanup, when the identity changes, which is when
  // the measured minimum width starts over; a re-render must not do that.
  const measure = useCallback(
    (root: HTMLSpanElement | null) =>
      observeFacepile({
        onCount: setVisibleCount,
        root,
        shownLength,
        total,
      }),
    [shownLength, total]
  );

  const small = size === "sm";
  const hasPlaceholder = placeholder !== undefined && placeholder !== null;
  const controlOpen = hiddenCount > 0 && open !== null;

  const onClick = interactive
    ? (event: MouseEvent) => {
        event.stopPropagation();
        setOpen((current) => (current === "click" ? null : "click"));
      }
    : undefined;

  const onKeyDown = (event: KeyboardEvent) => {
    if (interactive && (event.key === "Enter" || event.key === " ")) {
      event.stopPropagation();
    }
  };

  const controlProps = {
    "aria-hidden": hiddenCount === 0 || undefined,
    "aria-label": moreLabel(hiddenCount),
    className: cn(
      "pointer-events-auto absolute z-0 inline-flex cursor-(--ck-action-cursor) items-center justify-center rounded-full border border-border bg-panel text-xs text-text-muted",
      small ? "h-6 min-w-6 ps-1 pe-0.5" : "h-7 min-w-7 ps-1.5 pe-1",
      hiddenCount === 0 && "invisible"
    ),
    onClick,
    onKeyDown,
    tabIndex: interactive && hiddenCount > 0 ? 0 : -1,
  };

  const count = <span>{`+${hiddenCount || total}`}</span>;

  // The component lets the tooltip create the count button (triggerAsChild
  // false) when interactive and clones the count span otherwise. The same
  // element is passed in here, because the tooltip does not take styling.
  const control = interactive ? (
    <button type="button" {...controlProps}>
      {count}
    </button>
  ) : (
    <span {...controlProps}>{count}</span>
  );

  return (
    <span
      className={cn(
        "relative inline-flex min-w-0 items-center overflow-hidden select-none",
        small ? "max-w-28" : "max-w-32"
      )}
      data-ck-facepile
      ref={measure}
    >
      <span
        className={cn(
          "pointer-events-none relative isolate z-10 flex shrink-0 items-center",
          small ? "-space-x-1.5" : "-space-x-2"
        )}
      >
        {shownLength === 0 && hasPlaceholder ? (
          <span
            className="pointer-events-auto relative inline-flex shrink-0"
            data-page-facepile-avatar
          >
            {placeholder}
          </span>
        ) : (
          shown.map((person, index) => (
            <FacepileAvatar
              blockInitial={hasPlaceholder}
              front={front}
              index={index}
              key={person.id}
              reducedMotion={reducedMotion}
              total={shownLength}
              visibleCount={visibleCount}
            >
              {person.avatar}
            </FacepileAvatar>
          ))
        )}
      </span>
      <TooltipHint
        align="end"
        content={
          <TooltipProvider>
            <div className="flex max-h-64 flex-col gap-2 overflow-y-auto p-2">
              {people.slice(visibleCount).map((person) => (
                <div className="flex items-center gap-2" key={person.id}>
                  {person.avatar}
                  <span className="text-sm text-text">
                    {person.label ?? person.name}
                  </span>
                </div>
              ))}
            </div>
          </TooltipProvider>
        }
        interactive={interactive}
        onOpenChange={(next) => {
          setOpen(next ? "hover" : null);
        }}
        open={controlOpen}
        side="bottom"
        sideOffset={overflowSideOffset}
        variant="rich"
      >
        {control}
      </TooltipHint>
    </span>
  );
};

"use client";

import {
  ATTACHMENT_CONTENT_PATHS,
  HOST_AUTH_HEADER,
  HOST_ORIGIN,
} from "@/lib/host";
import {
  createContext,
  useCallback,
  useContext,
  useSyncExternalStore,
} from "react";
import type { ReactNode } from "react";

/*
 * Profile picture source: the hook, the URL classifier, the profile-picture
 * resolver and a cached image asset query. A small cache holds the results
 * with a key, stale time, garbage collection time, retry rules and mount
 * rule, and the asset resolver is pluggable so a host without that backend can
 * resolve assets from local data.
 */

const noCleanup = () => {
  // Nothing was subscribed or the failure is already recorded on the entry.
};

const IMAGE_CACHE_TTL_MS = 4 * 60 * 1000;
const PROFILE_PICTURE_CACHE_KEY = ["profile-picture"] as const;

/** Blob types that get an object URL. Others are used as data URLs. */
const OBJECT_URL_TYPES: ReadonlySet<string> = new Set([
  "image/avif",
  "image/bmp",
  "image/gif",
  "image/jpeg",
  "image/jpg",
  "image/png",
  "image/vnd.microsoft.icon",
  "image/webp",
  "image/x-icon",
  "image/x-png",
]);

/** What a resolver answers for an asset: a download, or a deleted file. */
export type AssetResolution =
  | {
      downloadUrl: string;
      kind: "available";
      requestHeaders?: Record<string, string>;
    }
  | { kind: "permanently-deleted" }
  | { kind: "trashed"; libraryFileId?: string };

export interface ProfileImageResolver {
  /** The cache scope; the query key is `["file", "image-src", url, ...cacheKey]`. */
  cacheKey: readonly string[];
  resolveAsset: (url: string) => Promise<AssetResolution>;
}

/** Resolves a profile picture with the host authentication header. */
export const profilePictureResolver: ProfileImageResolver = {
  cacheKey: PROFILE_PICTURE_CACHE_KEY,
  // oxlint-disable-next-line require-await -- The resolver answers with Promise.resolve; the interface is asynchronous.
  resolveAsset: async (url) => ({
    downloadUrl: url,
    kind: "available",
    requestHeaders: {
      [HOST_AUTH_HEADER]: "1",
      originator: "ComposerKit",
    },
  }),
};

/** Matches content URLs on the current host origin. */
export const isEstuaryUrl = (url: string | null | undefined): boolean => {
  if (url === null || url === undefined || url === "") {
    return false;
  }

  try {
    const parsed = new URL(url);

    return (
      (parsed.protocol === "https:" || parsed.protocol === "http:") &&
      parsed.origin === HOST_ORIGIN &&
      ATTACHMENT_CONTENT_PATHS.some(
        (path) =>
          parsed.pathname === path || parsed.pathname.startsWith(`${path}/`)
      )
    );
  } catch {
    return false;
  }
};

/** The asset id behind the file service schemes. */
const assetIdOf = (url: string) => {
  for (const scheme of ["file-service://", "sediment://"]) {
    if (url.startsWith(scheme)) {
      return url.replace(scheme, "");
    }
  }

  return url;
};

interface DownloadResult {
  dataUrl: string;
  downloadUrl: string;
  kind: "download";
  objectUrl: string | null;
}

interface DeletedResult {
  kind: "deleted";
}

type CachedResult = DeletedResult | DownloadResult;

/** A running fetch of an entry: with cancellation and resumption. */
interface Fetch {
  cancel: () => void;
  promise: Promise<CachedResult>;
  resume: () => void;
}

interface CacheEntry {
  collect: ReturnType<typeof setTimeout> | null;
  /** The query status is "error": the last fetch failed after its retries. */
  error: boolean;
  fetch: Fetch | null;
  /** An error marks the query invalidated, so it is stale until a fetch succeeds. */
  invalidated: boolean;
  key: string;
  listeners: Set<() => void>;
  /** fetchStatus is "paused": offline, or the page hidden between retries. */
  paused: boolean;
  result: CachedResult | null;
  updatedAt: number;
}

interface ImageSnapshot {
  dataUrl: string | null;
  isError: boolean;
  isLoading: boolean;
  src: string | null;
}

const entries = new Map<string, CacheEntry>();
const snapshots = new Map<string, ImageSnapshot>();

const keyOf = (url: string, resolver: ProfileImageResolver) =>
  JSON.stringify(["file", "image-src", url, ...resolver.cacheKey]);

const notify = (entry: CacheEntry) => {
  for (const listener of entry.listeners) {
    listener();
  }
};

/**
 * The object URL is revoked in a timeout of zero, after the entry no
 * longer holds it (the data was replaced, or the query was removed).
 */
const revoke = (result: CachedResult | null) => {
  if (result?.kind === "download" && result.objectUrl !== null) {
    const { objectUrl } = result;

    setTimeout(() => {
      URL.revokeObjectURL(objectUrl);
    }, 0);
  }
};

const removeEntry = (entry: CacheEntry) => {
  revoke(entry.result);

  if (entries.get(entry.key) === entry) {
    entries.delete(entry.key);
    snapshots.delete(entry.key);
  }
};

/**
 * Query.scheduleGc: after gcTime (four minutes) the entry is removed unless
 * a reader is subscribed or a fetch is running.
 */
const scheduleGc = (entry: CacheEntry) => {
  if (entry.collect !== null) {
    clearTimeout(entry.collect);
  }

  entry.collect = setTimeout(() => {
    entry.collect = null;

    if (entry.listeners.size === 0 && entry.fetch === null) {
      removeEntry(entry);
    }
  }, IMAGE_CACHE_TTL_MS);
};

const getEntry = (key: string): CacheEntry => {
  let entry = entries.get(key);

  if (entry === undefined) {
    entry = {
      collect: null,
      error: false,
      fetch: null,
      invalidated: false,
      key,
      listeners: new Set(),
      paused: false,
      result: null,
      updatedAt: 0,
    };
    entries.set(key, entry);
    scheduleGc(entry);
  }

  return entry;
};

/** Retry transient network failures without refetching on window focus. */
const MAX_RETRIES = 4;
const RETRY_BASE_DELAY_MS = 800;
const RETRY_MAX_DELAY_MS = 24_000;
const TOO_EARLY = 425;
const SERVER_ERROR_FIRST = 500;
const SERVER_ERROR_LAST = 599;

/** The numeric `status` of an error, if it has one. */
const statusOf = (error: Error & { status?: number }): number | null =>
  // oxlint-disable-next-line anti-slop/no-runtime-typeof -- A resolver may attach any value as status.
  typeof error.status === "number" ? error.status : null;

/** A download answered with a non-OK HTTP status. */
class HttpStatusError extends Error {
  readonly status: number;

  constructor(status: number) {
    super(`The avatar image download did not complete with HTTP ${status}`);
    this.name = "HttpStatusError";
    this.status = status;
  }
}

/** What a failed download throws: an Error, with a `status` for an HTTP failure. */
// oxlint-disable-next-line anti-slop/no-unknown-parameters -- A catch clause binds unknown; this is the boundary that makes it an Error.
const asError = (thrown: unknown): Error =>
  thrown instanceof Error
    ? thrown
    : new Error("The avatar image download did not complete", {
        cause: thrown,
      });

const isRetryableStatus = (status: number) =>
  status === 408 ||
  status === TOO_EARLY ||
  status === 429 ||
  (status >= SERVER_ERROR_FIRST && status <= SERVER_ERROR_LAST);

const shouldRetry = (failureCount: number, error: Error) => {
  if (failureCount >= MAX_RETRIES) {
    return false;
  }

  const status = statusOf(error);

  return status === null || status === 0 || isRetryableStatus(status);
};

/** 800ms, 1600ms, then double the delay up to 24s. */
const retryDelay = (failureCount: number) =>
  Math.min(RETRY_BASE_DELAY_MS * 2 ** failureCount, RETRY_MAX_DELAY_MS);

/** Tracks page visibility and connectivity for the query cache. */
let online = true;
let environmentWatched = false;

const isFocused = () => document.visibilityState !== "hidden";

const canRun = () => isFocused() && online;

/** Query.onFocus and Query.onOnline: continue a paused retryer. */
const resumeFetches = () => {
  for (const entry of entries.values()) {
    entry.fetch?.resume();
  }
};

const watchEnvironment = () => {
  if (environmentWatched) {
    return;
  }

  environmentWatched = true;
  online = navigator.onLine;

  document.addEventListener("visibilitychange", () => {
    if (isFocused()) {
      resumeFetches();
    }
  });
  window.addEventListener("online", () => {
    online = true;
    resumeFetches();
  });
  window.addEventListener("offline", () => {
    online = false;
  });
};

/** The blob as a data URL. */
const readDataUrl = async (blob: Blob) => {
  const { promise, reject, resolve } = Promise.withResolvers<string>();
  const reader = new FileReader();

  reader.addEventListener("load", () => {
    // oxlint-disable-next-line anti-slop/no-runtime-typeof -- FileReader.result is a string, an ArrayBuffer or null.
    if (typeof reader.result === "string") {
      resolve(reader.result);
    } else {
      reject(new Error("The image could not be read as a data URL"));
    }
  });
  reader.addEventListener("error", () => {
    reject(
      reader.error ?? new Error("The image could not be read as a data URL")
    );
  });
  reader.readAsDataURL(blob);

  return await promise;
};

/** Downloads image bytes through the asset resolver. */
const downloadAsset = async (
  url: string,
  resolver: ProfileImageResolver,
  signal: AbortSignal
): Promise<CachedResult> => {
  const resolution = await resolver.resolveAsset(assetIdOf(url));

  signal.throwIfAborted();

  if (resolution.kind !== "available") {
    return { kind: "deleted" };
  }

  const response = await fetch(resolution.downloadUrl, {
    headers: resolution.requestHeaders,
    signal,
  });

  // Reject a non-OK response before reading its bytes, so an HTTP
  // failure reaches the retry rules with its status instead of being cached.
  if (!response.ok) {
    throw new HttpStatusError(response.status);
  }

  const blob = await response.blob();
  const dataUrl = await readDataUrl(blob);

  signal.throwIfAborted();

  return {
    dataUrl,
    downloadUrl: resolution.downloadUrl,
    kind: "download",
    objectUrl: OBJECT_URL_TYPES.has(blob.type)
      ? URL.createObjectURL(blob)
      : null,
  };
};

const isFresh = (entry: CacheEntry) =>
  entry.result !== null &&
  !entry.invalidated &&
  Date.now() - entry.updatedAt < IMAGE_CACHE_TTL_MS;

/**
 * A failed fetch is retried by shouldRetry
 * after retryDelay. Between retries a hidden page or an offline browser
 * pauses the fetch until the page is shown or the browser is online. The
 * state before the fetch is kept so cancelling it (the last reader leaves,
 * as the queryFn reads the abort signal) restores that state.
 */
const startFetch = async (
  entry: CacheEntry,
  url: string,
  resolver: ProfileImageResolver
): Promise<CachedResult> => {
  watchEnvironment();

  const controller = new AbortController();
  const before = { error: entry.error, invalidated: entry.invalidated };
  const { promise, reject, resolve } = Promise.withResolvers<CachedResult>();

  let settled = false;
  let wake: (() => void) | null = null;
  let resume: (() => void) | null = null;

  // The "fetch" action: a query without data starts again as pending.
  if (entry.result === null) {
    entry.error = false;
  }

  entry.paused = false;
  promise.catch(noCleanup);

  const finish = () => {
    entry.fetch = null;
    entry.paused = false;
    scheduleGc(entry);
  };

  const wait = async (milliseconds: number) => {
    const gate = Promise.withResolvers<null>();

    const timer = setTimeout(() => {
      gate.resolve(null);
    }, milliseconds);

    wake = () => {
      clearTimeout(timer);
      gate.resolve(null);
    };

    await gate.promise;
    wake = null;
  };

  const pause = async () => {
    const gate = Promise.withResolvers<null>();

    wake = () => {
      gate.resolve(null);
    };

    resume = () => {
      if (canRun()) {
        gate.resolve(null);
      }
    };

    entry.paused = true;
    notify(entry);
    await gate.promise;
    wake = null;
    resume = null;

    if (!settled) {
      entry.paused = false;
      notify(entry);
    }
  };

  const attempt = async (failureCount: number): Promise<CachedResult> => {
    try {
      return await downloadAsset(url, resolver, controller.signal);
    } catch (error_) {
      const error = asError(error_);

      if (settled || !shouldRetry(failureCount, error)) {
        throw error;
      }

      await wait(retryDelay(failureCount));

      if (!settled && !canRun()) {
        await pause();
      }

      if (settled) {
        throw error;
      }

      return await attempt(failureCount + 1);
    }
  };

  const run = async () => {
    if (!online) {
      await pause();
    }

    return await attempt(0);
  };

  entry.fetch = {
    cancel: () => {
      if (settled) {
        return;
      }

      settled = true;
      wake?.();
      controller.abort();
      entry.error = before.error;
      entry.invalidated = before.invalidated;
      finish();
      notify(entry);
      reject(new Error("CancelledError"));
    },
    promise,
    resume: () => {
      resume?.();
    },
  };

  const succeed = (result: CachedResult) => {
    if (settled) {
      revoke(result);

      return;
    }

    settled = true;
    revoke(entry.result);
    entry.result = result;
    entry.error = false;
    entry.invalidated = false;
    entry.updatedAt = Date.now();
    finish();
    notify(entry);
    resolve(result);
  };

  const fail = (error: Error) => {
    if (settled) {
      return;
    }

    settled = true;
    entry.error = true;
    entry.invalidated = true;
    finish();
    notify(entry);
    reject(error);
  };

  const settle = async () => {
    let result: CachedResult;

    try {
      result = await run();
    } catch (error) {
      fail(asError(error));

      return;
    }

    succeed(result);
  };

  settle().catch(noCleanup);

  notify(entry);

  return await promise;
};

/**
 * An observer mounting or fetchQuery: starts a fetch unless the cached
 * result is younger than four minutes (staleTime). A running fetch is
 * shared. A query in the error state with no data starts again, as the
 * default retryOnMount is true, and so does one that holds data from
 * before its last failure, because a failure leaves it stale.
 */
const loadEntry = async (url: string, resolver: ProfileImageResolver) => {
  const entry = getEntry(keyOf(url, resolver));

  if (isFresh(entry) && entry.result !== null) {
    return entry.result;
  }

  return await (entry.fetch?.promise ?? startFetch(entry, url, resolver));
};

/** Fetches the picture into the cache and returns its data URL, or the URL when it is not an estuary URL. */
export const prefetchProfileImage = async (
  url: string | null | undefined,
  resolver: ProfileImageResolver = profilePictureResolver
): Promise<string | null> => {
  if (url === null || url === undefined || !isEstuaryUrl(url)) {
    return null;
  }

  const result = await loadEntry(url, resolver);

  return result.kind === "download" ? result.dataUrl : null;
};

/** Drops every cached picture, like removing the queries from the client. */
export const clearProfileImageCache = () => {
  const listeners: (() => void)[] = [];

  for (const entry of entries.values()) {
    entry.fetch?.cancel();

    if (entry.collect !== null) {
      clearTimeout(entry.collect);
      entry.collect = null;
    }

    revoke(entry.result);
    listeners.push(...entry.listeners);
  }

  entries.clear();
  snapshots.clear();

  for (const listener of listeners) {
    listener();
  }
};

export interface ProfileImage {
  isError: boolean;
  src: string | null | undefined;
}

const idleSnapshot: ImageSnapshot = {
  dataUrl: null,
  isError: false,
  isLoading: false,
  src: null,
};

/** Stable snapshot per entry state, so useSyncExternalStore does not loop. */
const snapshotOf = (key: string): ImageSnapshot => {
  const entry = entries.get(key);

  if (entry === undefined) {
    return idleSnapshot;
  }

  const { result } = entry;
  const download = result?.kind === "download" ? result : null;
  const dataUrl = download?.dataUrl ?? null;
  const src = download?.objectUrl ?? download?.dataUrl ?? null;
  // isLoading is fetching and pending: a paused fetch is not loading.
  const isLoading = entry.fetch !== null && !entry.paused && result === null;
  const previous = snapshots.get(key);

  if (
    previous !== undefined &&
    previous.dataUrl === dataUrl &&
    previous.src === src &&
    previous.isLoading === isLoading &&
    previous.isError === entry.error
  ) {
    return previous;
  }

  const next = { dataUrl, isError: entry.error, isLoading, src };

  snapshots.set(key, next);

  return next;
};

/**
 * The cached download for a URL while
 * enabled, with the data URL, the displayable src (object URL, else data
 * URL), loading and error state. A reader that subscribes starts the
 * download when the cached result is missing, stale or left by a failure.
 * The last reader leaving cancels a running download.
 */
const useCachedAsset = (
  url: string,
  resolver: ProfileImageResolver
): ImageSnapshot => {
  const key = url === "" ? "" : keyOf(url, resolver);

  const subscribe = useCallback(
    (onChange: () => void) => {
      if (key === "") {
        return noCleanup;
      }

      const entry = getEntry(key);

      entry.listeners.add(onChange);

      if (entry.collect !== null) {
        clearTimeout(entry.collect);
        entry.collect = null;
      }

      loadEntry(url, resolver).catch(noCleanup);

      return () => {
        entry.listeners.delete(onChange);

        if (entry.listeners.size === 0) {
          entry.fetch?.cancel();
          scheduleGc(entry);
        }
      };
    },
    [key, resolver, url]
  );

  return useSyncExternalStore(
    subscribe,
    () => (key === "" ? idleSnapshot : snapshotOf(key)),
    () => idleSnapshot
  );
};

const ProfileImageContext = createContext<ProfileImageResolver>(
  profilePictureResolver
);

/** Supplies the asset resolver that the profile picture hook downloads with. */
export const ProfileImageProvider = ({
  children,
  resolver,
}: {
  children?: ReactNode;
  resolver: ProfileImageResolver;
}) => (
  <ProfileImageContext.Provider value={resolver}>
    {children}
  </ProfileImageContext.Provider>
);

/**
 * The picture for a profile avatar. An estuary URL goes through the
 * resolver and the cache, and answers its data URL (or object URL) once
 * downloaded, with isError set if the download failed. Any other URL is
 * answered as it is when `allowExternalUrls` (default true), else null.
 */
export const useProfileImage = (
  url: string | null | undefined,
  options: { allowExternalUrls?: boolean } = {}
): ProfileImage => {
  const resolver = useContext(ProfileImageContext);
  const allowExternalUrls = options.allowExternalUrls ?? true;
  const estuary = isEstuaryUrl(url);
  const asset = useCachedAsset(estuary ? (url ?? "") : "", resolver);

  if (estuary) {
    return { isError: asset.isError, src: asset.dataUrl ?? asset.src };
  }

  return { isError: false, src: allowExternalUrls ? (url ?? null) : null };
};

/*
 * The loaded image fade of the avatar. Tailwind cannot define @keyframes, so
 * this holds the loaded-state rules and
 * _image-loaded_1l93m_2: the fade plays over
 * --motion-duration-fast with ease-out, is off when :root has
 * data-ck-reduced-motion="true", and, with no data-ck-reduced-motion attribute,
 * is off under prefers-reduced-motion: reduce.
 */

@keyframes ck-image-fade {
  0% {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

.loaded {
  animation: ck-image-fade var(--motion-duration-fast) ease-out;
}

:global(:root[data-ck-reduced-motion="true"]) .loaded {
  animation: none;
}

@media (prefers-reduced-motion: reduce) {
  :global(:root:not([data-ck-reduced-motion])) .loaded {
    animation: none;
  }
}

"use client";

// Lucide artwork is covered by components/icon/lucide.license.

/* oxlint-disable anti-slop/no-shape-in-symbol-names -- The public names are shape, animateShape and AvatarShape. */

import {
  useAccountProfile,
  useAuth,
  useProfileVisibility,
  useSpacePersonAvatar,
} from "@/components/avatar/account";
import { AvatarShape } from "@/components/avatar/avatar-shape";
import type { AvatarShapeName } from "@/components/avatar/avatar-shape";
import { useProfileImage } from "@/components/avatar/profile-image";
import { createIcon } from "@/components/icon";
import { TooltipHint } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";
import { useCallback, useState } from "react";
import type { ReactNode } from "react";

import styles from "./avatar.module.css";

export type AvatarSize =
  | "action"
  | "badge"
  | "fill"
  | "group"
  | "inline"
  | "lg"
  | "md"
  | "picker"
  | "preview"
  | "profile"
  | "response"
  | "row"
  | "sm"
  | "xl"
  | "xs";

export type AvatarShapeOption = AvatarShapeName | "none";

// Size maps.
// Sizes are Tailwind utilities on a 0.25rem spacing. xs is the
// `icon-sm` utility, which is 18px.
const sizeClasses: Record<AvatarSize, string> = {
  action: "size-9",
  badge: "size-3",
  fill: "size-full",
  group: "size-7",
  inline: "size-4",
  lg: "size-20",
  md: "size-8",
  picker: "size-12",
  preview: "size-48",
  profile: "size-28",
  response: "size-5",
  row: "size-10",
  sm: "size-6",
  xl: "size-32",
  xs: "size-[18px]",
};

// text-5xl in the component is 3rem with a 3rem line height and heading-3xl
// tracking (-.025em), so it is spelled out rather than using the default.
const fontClasses: Record<AvatarSize, string> = {
  action: "text-sm",
  badge: "text-[6px] leading-none",
  fill: "text-[3rem] leading-[3rem] tracking-tight",
  group: "text-xs",
  inline: "text-[6px] leading-none",
  lg: "text-[28px]",
  md: "text-sm",
  picker: "text-lg",
  preview: "text-[3rem] leading-[3rem] tracking-tight",
  profile: "text-[40px]",
  response: "text-[10px] leading-none",
  row: "text-sm",
  sm: "text-xs",
  xl: "text-[40px]",
  xs: "text-[10px] leading-none",
};

const colorNames = ["purple", "blue", "green", "orange", "red"] as const;

type AvatarColorName = (typeof colorNames)[number];

const colorClasses: Record<AvatarColorName, string> = {
  blue: "bg-(--color-status-info-solid)",
  green: "bg-(--color-status-success-solid)",
  orange: "bg-(--color-status-warning-solid)",
  purple: "bg-(--color-status-discovery-solid)",
  red: "bg-(--color-status-danger-solid)",
};

const grayClass = "bg-(--color-neutral-strong-surface)";
const HASH_MULTIPLIER = 33;
const WHITESPACE = /\s+/u;

const trimmedOrNull = (value: string | null | undefined) => {
  const trimmed = value?.trim();

  return trimmed === undefined || trimmed.length === 0 ? null : trimmed;
};

/**
 * First letters of the first and last word of a name, uppercased. "?" when
 * the name has no words.
 */
export const getAvatarInitials = (name: string | null | undefined) => {
  const words = trimmedOrNull(name)?.split(WHITESPACE) ?? [];
  const first = words[0]?.charAt(0) ?? "";
  const last = words.length > 1 ? (words.at(-1)?.charAt(0) ?? "") : "";
  const initials = `${first}${last}`.toUpperCase();

  return initials.length > 0 ? initials : "?";
};

/** Hash the first word of the trimmed key into the avatar palette. */
export const getAvatarColorName = (
  key: string,
  offset = 0
): AvatarColorName => {
  let hash = 0;

  for (const character of key.trim().split(WHITESPACE, 1)[0]) {
    hash =
      (hash * HASH_MULTIPLIER + (character.codePointAt(0) ?? 0)) %
      colorNames.length;
  }

  return colorNames[(hash + offset) % colorNames.length];
};

/** Content the avatar can return as is; promises are not accepted. */
export type AvatarContent = Exclude<ReactNode, PromiseLike<unknown>>;

export interface AvatarProps {
  /** Makes the avatar `role="img"` with this label. Without it the avatar is decorative. */
  alt?: string;
  /** Redraws the outline as a morph and leaves rounding to the clip. */
  animateShape?: boolean;
  /** Hashed for the background color. Falls back to the trimmed name. */
  colorKey?: string;
  /** Fades the image in once it has loaded. */
  fadeIn?: boolean;
  /** Replaces the initials entirely. */
  fallback?: AvatarContent;
  /** Replaces the initials text, and the SVG that the badge and inline sizes draw it in. */
  fallbackIcon?: AvatarContent;
  hovered?: boolean;
  /** Shown instead of the image while it loads; the image stays hidden. */
  loadingFallback?: AvatarContent;
  /** `true` dims the avatar to 40%. Any non-nullish value, `false` too, adds the filter transition. */
  muted?: boolean | null;
  name?: string | null;
  onImageError?: () => void;
  overlay?: ReactNode;
  referrerPolicy?: React.HTMLAttributeReferrerPolicy;
  shape?: AvatarShapeOption;
  size?: AvatarSize;
  src?: string | null;
}

type ImageState = "error" | "loaded" | "loading";

// Presence classes: muted is filter opacity(40%).
// The presence transition covers the filter over --motion-duration-fast.
// The component switches it off only when :root has data-ck-reduced-motion="true".
const mutedClass = "[filter:opacity(40%)]";

const presenceClass =
  "transition-[filter] duration-(--motion-duration-fast) [:root[data-ck-reduced-motion=true]_&]:transition-none";

const isPresent = (value: AvatarContent) =>
  value !== undefined && value !== null;

const mutedClasses = (muted: boolean | null | undefined) =>
  cn(
    muted !== null && muted !== undefined && presenceClass,
    muted === true && mutedClass
  );

const colorClassFor = (
  colorKey: string | undefined,
  name: string | null | undefined
) => {
  const source =
    colorKey !== undefined && colorKey !== "" ? colorKey : trimmedOrNull(name);

  return source === null ? grayClass : colorClasses[getAvatarColorName(source)];
};

const initialsContent = (
  size: AvatarSize,
  text: string,
  icon: AvatarContent
): AvatarContent => {
  if (isPresent(icon)) {
    return icon;
  }

  if (size !== "badge" && size !== "inline") {
    return text;
  }

  return (
    <svg aria-hidden="true" className="size-full" viewBox="0 0 12 12">
      <text
        dominantBaseline="central"
        fill="currentColor"
        textAnchor="middle"
        x="6"
        y="6"
      >
        {text}
      </text>
    </svg>
  );
};

const AvatarFallback = ({
  alt,
  animateShape = false,
  colorKey,
  fallback,
  fallbackIcon,
  muted,
  name,
  shape = "circle",
  size = "sm",
}: AvatarProps) => {
  if (isPresent(fallback)) {
    return fallback;
  }

  const initials = getAvatarInitials(name);
  const tiny = size === "badge" || size === "inline" || size === "xs";

  const text = tiny
    ? String.fromCodePoint(initials.codePointAt(0) ?? 0)
    : initials;

  const labelled = alt !== undefined && alt !== "";

  return (
    <span
      aria-hidden={labelled ? undefined : true}
      aria-label={labelled ? alt : undefined}
      className={cn(
        "flex shrink-0 items-center justify-center font-normal text-(--color-avatar-on-surface) select-none",
        mutedClasses(muted),
        !animateShape && shape === "circle" && "rounded-full",
        colorClassFor(colorKey, name),
        sizeClasses[size],
        fontClasses[size]
      )}
      role={labelled ? "img" : undefined}
    >
      {initialsContent(size, text, fallbackIcon)}
    </span>
  );
};

const AvatarImage = (props: AvatarProps & { src: string }) => {
  const {
    alt,
    animateShape,
    fadeIn,
    loadingFallback,
    muted,
    onImageError,
    referrerPolicy,
    shape,
    size = "sm",
    src,
  } = props;

  const [state, setState] = useState<ImageState>("loading");
  const tracksLoad = (loadingFallback ?? null) !== null || fadeIn === true;
  const waiting = loadingFallback !== undefined && loadingFallback !== null;

  // The component reads `complete` when the element mounts, so a cached image
  // settles without waiting for a load event. A server rendered image can
  // also fail before React attaches onError; the component renders on the client
  // only, where the handler is always there first, so a failure that is
  // already complete reports the same error here.
  const trackImage = useCallback(
    (image: HTMLImageElement | null) => {
      if (image?.complete !== true) {
        return;
      }

      if (tracksLoad) {
        setState(image.naturalWidth > 0 ? "loaded" : "error");
      } else if (image.naturalWidth === 0) {
        setState("error");
        onImageError?.();
      }
    },
    [tracksLoad, onImageError]
  );

  if (state === "error") {
    return <AvatarFallback {...props} />;
  }

  const showLoadingFallback = state === "loading" && waiting;

  return (
    <>
      {/* oxlint-disable-next-line nextjs/no-img-element -- Avatar URLs are arbitrary remote images. */}
      <img
        alt={alt}
        className={cn(
          "shrink-0 object-cover",
          mutedClasses(muted),
          fadeIn === true && (state === "loaded" ? styles.loaded : "opacity-0"),
          animateShape !== true &&
            (shape === undefined || shape === "circle") &&
            "rounded-full",
          sizeClasses[size]
        )}
        draggable={false}
        hidden={showLoadingFallback}
        onError={() => {
          setState("error");
          onImageError?.();
        }}
        onLoad={
          tracksLoad
            ? () => {
                setState("loaded");
              }
            : undefined
        }
        ref={trackImage}
        referrerPolicy={referrerPolicy}
        src={src}
      />
      {state === "loading" ? loadingFallback : null}
    </>
  );
};

/**
 * Round (or clipped) avatar showing an image, or initials when there is no
 * image or it fails to load.
 */
export const Avatar = (props: AvatarProps) => {
  const { animateShape, hovered, overlay, shape, size = "sm", src } = props;

  const content =
    src === undefined || src === null ? (
      <AvatarFallback {...props} />
    ) : (
      <AvatarImage {...props} key={src} src={src} />
    );

  if (shape === "none") {
    if (overlay === undefined || overlay === null) {
      return content;
    }

    return (
      <span className={cn("relative inline-flex shrink-0", sizeClasses[size])}>
        {content}
        {overlay}
      </span>
    );
  }

  if (
    (shape === undefined || shape === "circle") &&
    (overlay === undefined || overlay === null) &&
    animateShape !== true
  ) {
    return content;
  }

  return (
    <AvatarShape
      animateShape={animateShape}
      hovered={hovered}
      shape={shape ?? "circle"}
    >
      {content}
      {overlay}
    </AvatarShape>
  );
};

export interface ProfileAvatarProps {
  avatarUrl?: string | null;
  colorKey?: string;
  fadeIn?: boolean;
  /** Keeps the loading fallback up while the profile is still loading. */
  loading?: boolean;
  loadingFallback?: AvatarContent;
  muted?: boolean | null;
  name?: string | null;
  size?: AvatarSize;
}

/**
 * Avatar for a person: the picture when profile pictures are visible
 * (useProfileVisibility, which needs AccountServicesProvider), otherwise
 * initials. The picture goes through useProfileImage.
 */
export const ProfileAvatar = ({
  avatarUrl,
  colorKey,
  fadeIn,
  loading,
  loadingFallback,
  muted,
  name,
  size = "md",
}: ProfileAvatarProps) => {
  const { isProfileVisible } = useProfileVisibility();
  const { isError, src } = useProfileImage(isProfileVisible ? avatarUrl : null);

  const pending =
    isProfileVisible &&
    (Boolean(loading) ||
      (avatarUrl !== null &&
        avatarUrl !== undefined &&
        (src === null || src === undefined) &&
        !isError));

  return (
    <Avatar
      alt=""
      colorKey={colorKey}
      fadeIn={fadeIn}
      fallback={pending ? loadingFallback : undefined}
      loadingFallback={loadingFallback}
      muted={muted}
      name={name}
      size={size}
      src={src}
    />
  );
};

export interface AccountAvatarProps {
  /** Account user id of the person. Its part before "__" is matched with the signed-in user. */
  accountUserId?: string;
  avatarUrl?: string | null;
  fadeIn?: boolean;
  loading?: boolean;
  loadingFallback?: AvatarContent;
  muted?: boolean | null;
  name?: string | null;
  /** Whether the person lookup runs. Defaults to true. */
  profileQueryEnabled?: boolean;
  size?: AvatarSize;
}

const AUTH0_AVATAR_PREFIX = "https://cdn.auth0.com/avatars/";

/** The part before "__" matches the signed-in user's. */
const isSameUser = (userId: string | null, accountUserId: string | undefined) =>
  userId !== null && accountUserId?.split("__")[0] === userId.split("__")[0];

/** The account picture, unless auth0 generated it. */
const accountPictureOf = (
  signedIn: boolean,
  imageUrl: string | null | undefined
) => {
  if (!signedIn || (imageUrl ?? "").startsWith(AUTH0_AVATAR_PREFIX)) {
    return null;
  }

  return imageUrl;
};

/**
 * Avatar for a person of the signed-in account. For the signed-in user the
 * account profile picture is used (not an auth0 generated one), then the
 * given avatarUrl, then the picture of the person lookup. It needs
 * AccountServicesProvider.
 */
export const AccountAvatar = ({
  accountUserId,
  avatarUrl,
  fadeIn,
  loading,
  loadingFallback,
  muted,
  name,
  profileQueryEnabled = true,
  size = "sm",
}: AccountAvatarProps) => {
  const { accountId, userId } = useAuth();

  const isSignedInUser = isSameUser(userId, accountUserId);

  const { data: profile, isLoading: profileLoading } = useAccountProfile({
    accountId,
    enabled: isSignedInUser && accountId !== null,
    userId,
  });

  const profileImageUrl = profile?.imageUrl;

  const accountImageUrl = accountPictureOf(isSignedInUser, profileImageUrl);

  const lookupKey =
    (accountImageUrl ?? null) === null && (avatarUrl ?? null) === null
      ? (accountUserId ?? null)
      : null;

  const lookedUp = useSpacePersonAvatar(lookupKey, profileQueryEnabled);

  return (
    <ProfileAvatar
      avatarUrl={accountImageUrl ?? avatarUrl ?? lookedUp}
      colorKey={accountUserId}
      fadeIn={fadeIn}
      loading={
        Boolean(loading) ||
        (isSignedInUser && profileLoading && (avatarUrl ?? null) === null)
      }
      loadingFallback={loadingFallback}
      muted={muted}
      name={name}
      size={size}
    />
  );
};

